#!/usr/bin/env bash
# POST /o/{org}/oauth2/token and /oauth2/token under increasing concurrency, as a markdown table.
#
# run.sh §2 measures only the platform tier's bootstrap client. That secret is chosen by the
# operator, so it is hashed with Argon2id. The credentials a consuming application actually uses are
# generated by the server, and those are what this adds: it measures both side by side, so the
# difference between the two hashing schemes is visible on one instance.
#
# Needs the environment printed by setup-pkce-fixture.sh (ORG_ID, M2M_CLIENT_ID, M2M_CLIENT_SECRET)
# plus PLATFORM_BOOTSTRAP_CLIENT_ID/SECRET, and `ab`. Raise the token rate limit on the target first
# (see README.md), or the limiter is what gets measured. Requests per level: REQUESTS (default 400).
set -euo pipefail

CLAVARIS_BASE_URL="${CLAVARIS_BASE_URL:-http://localhost:8080}"
: "${ORG_ID:?run setup-pkce-fixture.sh first}"
: "${M2M_CLIENT_ID:?run setup-pkce-fixture.sh first}"
: "${M2M_CLIENT_SECRET:?run setup-pkce-fixture.sh first}"
: "${PLATFORM_BOOTSTRAP_CLIENT_ID:?same value the instance was started with}"
: "${PLATFORM_BOOTSTRAP_CLIENT_SECRET:?same value the instance was started with}"
REQUESTS="${REQUESTS:-400}"
LEVELS="${LEVELS:-1 3 10 30}"

BODY="$(mktemp)"
OUT="$(mktemp)"
trap 'rm -f "${BODY}" "${OUT}"' EXIT
printf 'grant_type=client_credentials' >"${BODY}"

measure() {
  local label="$1" url="$2" credentials="$3" level="$4"
  # Warm up once so the first, JIT-cold requests are not in the sample.
  ab -q -n 30 -c 3 -A "${credentials}" -p "${BODY}" -T application/x-www-form-urlencoded "${url}" >/dev/null 2>&1 || true
  ab -q -n "${REQUESTS}" -c "${level}" -A "${credentials}" -p "${BODY}" \
    -T application/x-www-form-urlencoded "${url}" >"${OUT}" 2>&1 || true
  local p50 p95 p99 rps failed non2xx
  p50="$(awk '$1=="50%"{print $2}' "${OUT}")"
  p95="$(awk '$1=="95%"{print $2}' "${OUT}")"
  p99="$(awk '$1=="99%"{print $2}' "${OUT}")"
  rps="$(awk '/Requests per second/{print $4}' "${OUT}")"
  failed="$(awk '/Failed requests/{print $3}' "${OUT}")"
  non2xx="$(awk '/Non-2xx responses/{print $3}' "${OUT}")"
  printf '| %s | %s | %sms | %sms | %sms | %s | %s |\n' \
    "${label}" "${level}" "${p50:-n/a}" "${p95:-n/a}" "${p99:-n/a}" "${rps:-n/a}" \
    "failed=${failed:-?} non2xx=${non2xx:-0}"
}

echo '| Client secret | Concurrency | p50 | p95 | p99 | req/s | Failures |'
echo '|---|---|---|---|---|---|---|'
for level in ${LEVELS}; do
  measure "tenant client (generated secret)" "${CLAVARIS_BASE_URL}/o/${ORG_ID}/oauth2/token" \
    "${M2M_CLIENT_ID}:${M2M_CLIENT_SECRET}" "${level}"
done
for level in ${LEVELS}; do
  measure "platform bootstrap (operator-chosen secret)" "${CLAVARIS_BASE_URL}/oauth2/token" \
    "${PLATFORM_BOOTSTRAP_CLIENT_ID}:${PLATFORM_BOOTSTRAP_CLIENT_SECRET}" "${level}"
done
